INSERT INTO SERVICE_FIELDS_VALUES (ID, SERVICE_FIELDS_TYPE_ID, ID_REQUEST, VALUE) VALUES (1917, 256, 224, 'Instalação de equipamento piso-teto no setor de manutenção do centro logístico: 1 - Instalação do suporte do evaporador. 2 - Posicionamento do evaporador 3 - Abertura para passagem de infraestrutura (tubulações, cabo e dreno) 4 - Criação de kit 5 - Posicionamento do condensador 6 - Colocação de calço de borrachas na condensadora. 7 - Criação de flanges na tubulação e aperto das porcas no evaporador 8 - Solda da tubulação na condensadora 9 - Pressurização do equipamento com nitrogênio. 10 - Verificação de vazamentos');
