INSERT INTO SERVICE_FIELDS_VALUES (ID, SERVICE_FIELDS_TYPE_ID, ID_REQUEST, VALUE) VALUES (3261, 34, 363, 'Bom dia!Solicito, por gentileza, o reparo dos tachões que, em razão da atividade realizada, se desprenderam, permanecendo apenas os parafusos expostos no local.Peço, por gentileza, a retirada dos parafusos, pois já ocasionaram um incidente (uma pessoa tropeçou np parafuso que prende os tachões), bem como a instalação de novos tachões para garantir a segurança da via.Desde já, agradeço.');
