INSERT INTO SERVICE_FIELDS_VALUES (ID, SERVICE_FIELDS_TYPE_ID, ID_REQUEST, VALUE) VALUES (4082, 295, 447, 'Realizada a manutenção corretiva do equipamento do aquário (AR-31)Atividades: Verificação da placa do evaporador.Troca dos sensores de degelo e tubular.Verificação na placa da condensadora.Verificação de sensores na placa da condensadora.Limpeza de conectores e placa da condensadora com limpa contato. Teste do equipamento. Medição de tensão, corrente, pressão e temperatura. Equipamento em funcionamento.');
